def strange_sort_list(lst):
    if not lst:
        return []

    sorted_lst = sorted(lst)
    output = []
    remaining = []

    for i in range(len(sorted_lst)):
        if i % 2 == 0:
            output.append(sorted_lst[i])
        else:
            remaining.append(sorted_lst[i])

    remaining.reverse()

    for i in range(len(remaining)):
        output.insert(i+1, remaining[i])

    return output

